mapper.select:
SELECT

FROM wms_inventory_log il
LEFT JOIN wms_product p ON il.product_id = p.id
LEFT JOIN wms_location l ON il.location_id = l.id

    AND il.warehouse_id = #{warehouseId}
    AND il.product_id = #{productId}
    AND il.batch_no LIKE CONCAT('%', #{batchNo}, '%')
    AND il.business_type = #{businessType}
    AND il.business_no LIKE CONCAT('%', #{businessNo}, '%')

ORDER BY il.operation_time DESC

    LIMIT #{query.pageNum}, #{query.pageSize}
